import {defaults,byId,exercises,equipment,plan,prescription,loadLabel,swaps,finishSession,level,volume,weekSessions,mainCount,availability,dayKey} from './engine.js';
const KEY='mo-training-v1';let state=defaults(),storageError=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);validateImport(parsed);if(parsed.version===1&&Array.isArray(parsed.history)&&parsed.profile&&parsed.loads){state={...defaults(),...parsed,profile:{...defaults().profile,...parsed.profile}}} }}catch{storageError=true}
let page=location.hash.slice(1)||'missions',notice='',swapping=false,month=new Date();let selectedHistory=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>String(n).padStart(2,'0'),time=n=>`${Math.floor(n/60)}:${fmt(n%60)}`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false}catch{storageError=true}}
function go(p){page=p;location.hash=p;render();window.scrollTo(0,0)}
const button=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function shell(content){const lv=level(state);return `<aside><a class="brand" href="#missions">MO<span>/</span><br>TRAINING<span class="brand-dot">®</span></a><div class="edition">PERSONAL TRAINING SYSTEM<br>VOL. 01 / MORGAN</div><nav aria-label="Navigation principale">${[['missions','01','Missions'],['calendar','02','Calendrier'],['progress','03','Progression'],['profile','04','Mon profil']].map(([id,n,label])=>`<a href="#${id}" class="${page===id?'active':''}"><span>${n}</span>${label}<b>↗</b></a>`).join('')}</nav><div class="aside-foot"><span class="tag">OBJECTIF ACTIF</span><p>PLUS FORT.<br>PLUS RÉGULIER.</p><small>Recomposition + hypertrophie</small><div class="level-mini">LVL. ${fmt(lv.level)}<span>${lv.within} / 300 XP</span></div><progress max="300" value="${lv.within}"></progress></div></aside><div class="workspace"><header><span>TON COPILOTE DE MUSCULATION</span><div class="profile-chip"><i>${esc(state.profile.name.slice(0,1).toUpperCase())}</i>${esc(state.profile.name)} <span>LVL ${fmt(lv.level)}</span></div></header><main>${storageError?'<div role="alert" class="alert">Sauvegarde locale indisponible. Exporte tes données avant de fermer cette page.</div>':''}${notice?`<div class="notice" role="status">${esc(notice)}${button('×','dismiss','icon','aria-label="Fermer le message"')}</div>`:''}${content}</main><footer>MO / TRAINING <span>LA RÉGULARITÉ FAIT LE RESTE.</span><a href="#science">Le moteur & ses sources ↗</a></footer></div>`}
function missions(){if(state.active)return session();const p=plan(state),weekly=weekSessions(state),count=weekly.length,avail=availability(state);return `<div class="page-heading"><div><p class="eyebrow">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</p><h1>LET’S<br><span>GET STRONG.</span></h1></div><div class="quest"><span class="eyebrow">QUÊTE DE LA SEMAINE</span><strong>${count}<small>/ 3</small></strong><div class="quest-blocks">${[0,1,2].map(i=>`<i class="${i<count?'done':''}"></i>`).join('')}</div><p>Chaque mission compte.</p></div></div><div class="dashboard"><section class="mission-card"><div class="card-top"><span class="tag dark">MISSION PRINCIPALE</span><span>↗ ${fmt(mainCount(state)+1)}</span></div><h2>FULL<br>BODY <span>${p.letter}</span></h2><p class="mission-caption">Construire du muscle. Une mission à la fois.</p><div class="mission-stats"><div><strong>${p.exercises.length}</strong><span>EXERCICES</span></div><div><strong>${p.exercises.reduce((a,e)=>a+e.sets,0)}</strong><span>SÉRIES</span></div><div><strong>≈ ${p.minutes}</strong><span>MINUTES</span></div></div>${button(state.profile.ready?'LANCER LA MISSION <span>↗</span>':'CALIBRER & COMMENCER <span>↗</span>','start-main','black wide',!avail.allowed?'disabled':'')}<p class="fine">${esc(avail.message)}</p></section><div class="side-cards"><section class="quick-card"><div class="card-top"><span class="tag">MODE EXPRESS</span><span class="electric">↯</span></div><h2>SHORT TIME.<br>REAL WORK.</h2><p>Un peu de temps, une vraie séance.</p><div class="quick-actions">${button('QUICK · 25 MIN ↗','start-quick','outline',!avail.allowed?'disabled':'')}${button('EMOM · 12 MIN ↗','start-emom','outline',!avail.allowed?'disabled':'')}</div></section><section class="coach-card"><span class="eyebrow">LE MOT DU COPILOTE</span><h3>${mainCount(state)<6?'D’abord, tes repères.':'La suite se construit.'}</h3><p>${mainCount(state)<6?'Deux séries par exercice pour démarrer. On apprend tes charges, puis on construit progressivement le volume.':'Trois séries par exercice. La charge augmente seulement quand tes séries sont maîtrisées.'}</p><a href="#science">Comprendre ma progression ↗</a></section></div></div><section class="line-section"><div class="section-title"><h3>TA SEMAINE. TON RYTHME.</h3><span>3 missions · séquence A → B → C</span></div><div class="week-strip">${['LUN','MAR','MER','JEU','VEN','SAM','DIM'].map((label,i)=>{const date=new Date();date.setDate(date.getDate()-(date.getDay()+6)%7+i);const done=weekly.some(s=>s.date===dayKey(date));return `<div class="${i>4?'off':''} ${dayKey(date)===dayKey()?'today':''}"><span>${label}</span><strong>${fmt(date.getDate())}</strong><small>${done?'✓ MISSION':i===5?'↗ GOLF':i===6?'REPOS':i%2===0?'LIBRE / SALLE':'FLEXIBLE'}</small></div>`}).join('')}</div></section><section class="line-section"><div class="section-title"><h3>DANS TA PROCHAINE MISSION</h3><span>Repos guidés · charges calibrées</span></div>${p.exercises.map((item,i)=>{const e=byId(item.id),l=prescription(state,e.id);return `<div class="exercise-row"><span class="row-number">${fmt(i+1)}</span><div><h4>${e.name}</h4><small>${e.muscle} · ${e.gear}</small></div><b>${item.sets} × ${e.min}–${e.max}</b><span class="row-load">${loadLabel(e,l.weight,l.mode)}</span></div>`}).join('')}${p.missing?'<p class="alert">Certains mouvements manquent avec ton matériel. Ajoute du matériel dans ton profil pour une mission complète.</p>':''}</section>`}
function start(type){if(!availability(state).allowed){notice=availability(state).message;render();return}if(!state.profile.ready){notice='Confirme ton profil et ton matériel, puis lance ta première mission.';go('profile');return}const p=plan(state,type);if(p.missing||!p.exercises.length){notice='Matériel insuffisant pour cette mission complète. Vérifie les équipements disponibles dans ton profil.';render();return}state.active={...p,id:crypto.randomUUID(),startedAt:Date.now(),records:[],index:0,stage:'warmup',rest:0,emomMinute:0,finisher:null};save();render()}
function session(){const a=state.active,item=a.exercises[a.index],e=item&&byId(item.id),l=e&&prescription(state,e.id),records=a.records.filter(r=>r.id===e?.id);let content='';
const top=`<div class="session-top"><span class="tag">${a.type} / ${esc(a.title)}</span>${button('Terminer plus tôt','stop','text-button')}</div>`;
if(a.stage==='warmup')content=`<p class="eyebrow">AVANT DE COMMENCER</p><h1>ON S’ÉCHAUFFE.</h1><p class="lead">5–8 minutes faciles, puis 1–2 séries légères du premier mouvement. Garde de l’énergie pour la suite.</p><div class="choice-grid">${[['Vélo','5 min · allure facile'],['Corde','3–5 min faciles · les 1 000 sauts sont facultatifs'],['Marche','5–8 min · allure confortable'],['Déjà échauffé','Passer à la mission']].map(([name,detail])=>button(`<strong>${name}</strong><small>${detail}</small>`,'warmup','choice',`data-value="${name}"`)).join('')}</div>`;
else if(a.stage==='rest')content=`<p class="eyebrow">${a.restKind==='exercise'?'AVANT LE PROCHAIN EXERCICE':'ENTRE DEUX SÉRIES'}</p><h1>RECOVERY.</h1><div class="rest-time">${time(a.rest)}</div><p class="lead">Mesure le repos sur ta Garmin.<br>Prolonge-le si ton souffle n’est pas revenu.</p>${button('JE SUIS PRÊT · CONTINUER ↗','continue','primary big')}`;
else if(a.stage==='calibrate')content=calibration(e,l)+button('⇄ SWAP · changer d’exercice','swap','outline')+(swapping?swapPanel(e):'');
else if(a.stage==='emom')content=emom(a);
else if(a.stage==='finishers')content=`<p class="eyebrow">MISSION PRINCIPALE VALIDÉE</p><h1>ENCORE<br>UN PEU DE JUS ?</h1><p class="lead">Un bonus facultatif. Tu peux aussi garder cette énergie pour ta prochaine séance.</p><div class="choice-grid">${[['core','GAINAGE','2 × 20–30 s de planche · 45 s de repos. Corps aligné ; arrête si la posture se dégrade.'],['conditioning','CONDITIONING','5 min de vélo modéré. Tu dois encore pouvoir parler.'],['mobility','MOBILITÉ','3 min douces : rotations d’épaules, chevilles et ouverture de hanches. Sans forcer.']].map(([v,n,d])=>button(`<strong>${n}</strong><small>${d}</small>`,'finisher','choice',`data-value="${v}"`)).join('')}</div>${button('TERMINER SANS FINISHER ↗','complete','primary big')}`;
else if(a.stage==='finisher')content=`<p class="eyebrow">BONUS FACULTATIF</p><h1>${{core:'GAINAGE.',conditioning:'CONDITIONING.',mobility:'MOBILITÉ.'}[a.finisher]}</h1><p class="lead">${{core:'2 × 20–30 secondes de planche. 45 secondes de repos. Respire et garde le bassin stable.',conditioning:'5 minutes de vélo à intensité modérée, sans chercher le sprint.',mobility:'3 minutes de mobilité douce des épaules, chevilles et hanches. Aucune amplitude forcée.'}[a.finisher]}</p>${button('FINISHER TERMINÉ ↗','complete','primary big')}${button('Finalement, je passe','skip-finisher','text-button')}`;
else content=`<div class="exercise-heading"><p class="eyebrow">EXERCICE ${fmt(a.index+1)} / ${fmt(a.exercises.length)} · ${e.muscle}</p><h1>${e.name}</h1><p class="lead">${e.cue}</p></div><div class="set-layout"><section class="set-card"><span class="tag">SÉRIE ${records.length+1} / ${item.sets}</span><div class="rep-target">${e.min}–${e.max}<small>RÉPÉTITIONS ${l.mode==='unilateral'?'PAR CÔTÉ':''}</small></div><h3>${loadLabel(e,l.weight,l.mode)}</h3><p>Objectif aujourd’hui : ${l.target} répétitions par série.</p><p>${esc(l.reason)}</p>${l.mode==='body'?'<p>Si trop facile, ralentis avec contrôle ou choisis une variante plus difficile via SWAP.</p>':''}<div class="set-dots">${Array.from({length:item.sets},(_,i)=>`<span class="${i<records.length?'done':''}">${i<records.length?'✓':i+1}</span>`).join('')}</div></section><form id="set-form"><h3>TA SÉRIE, EN VRAI.</h3><label>Charge réalisée ${l.mode==='body'?'(poids du corps)':'(même unité que ci-contre)'}<input name="weight" type="number" min="0" max="1000" step="0.25" value="${l.weight}" required ${l.mode==='body'?'readonly':''}></label><label>Répétitions réalisées ${l.mode==='unilateral'?'par côté (le plus faible)':''}<input name="reps" type="number" min="1" max="50" value="${l.target}" required></label><label>À la fin, tu aurais pu en faire…<select name="rir"><option value="2">Encore 2–3 · bien dosé</option><option value="4">Encore 4 ou plus · facile</option><option value="1">Encore 1 · très dur</option><option value="0">Aucune · à ma limite</option></select></label><button class="primary wide" type="submit">SÉRIE TERMINÉE ✓</button><p class="fine">Repos : ${time(e.rest)} entre séries · ${time(e.transition)} avant l’exercice suivant.</p></form></div><div class="session-actions">${button('⇄ SWAP · changer d’exercice','swap','outline',records.length?'disabled':'')}${button('Recalibrer la charge','recalibrate','text-button',records.length?'disabled':'')}${button('Douleur · arrêter ce mouvement','pain','text-button')}</div>${swapping?swapPanel(e):''}`;
return top+`<section class="session-content">${content}</section>`}
function calibration(e,l){return `<p class="eyebrow">CALIBRATION / ${e.gear}</p><h1>${e.name}</h1><p class="lead">Commence léger. Fais ${e.min} répétitions propres en gardant environ 3 répétitions possibles. Aucun test de charge maximale.</p><p>${e.cue}</p><form id="calibration-form" class="calibration"><label>Comment se charge cet appareil ?<select name="mode">${(e.gear==='machine'?[['stack','Une pile unique'],['side','Des disques de chaque côté'],['unilateral','Un côté à la fois']]:[[e.loadMode,{'pair':'Un haltère par main','single':'Un seul haltère','bar':'Total avec la barre','body':'Poids du corps','unilateral':'Un bras à la fois'}[e.loadMode]]]).map(([v,n])=>`<option value="${v}" ${v===l.mode?'selected':''}>${n}</option>`).join('')}</select></label><label>Charge d’essai en kg · par main/côté si applicable<input name="weight" type="number" min="${e.gear==='barre'?1:0}" max="1000" step="0.25" ${l.weight!==null?`value="${l.weight}"`:''} placeholder="Commence par une charge légère" required></label><label>Plus petit palier disponible (même unité)<input name="step" type="number" min="0.25" max="20" step="0.25" value="${l.step||1}" required></label><label>Après ${e.min} répétitions, il en reste…<select name="rir"><option value="3">2–3 possibles · charge adaptée</option><option value="5">4 ou plus · trop facile</option><option value="1">0–1 · trop lourd</option></select></label><p class="fine">${e.gear==='machine'?'Note la valeur de la pile, ou les disques par côté sans le poids inconnu du chariot. Recalibre si tu changes d’appareil.':e.gear==='barre'?'Compte toujours le poids de la barre dans le total.':'Note le poids d’un haltère, jamais la somme des deux.'}</p><button class="primary big" type="submit">ÉVALUER CET ESSAI ↗</button><p>Les essais ne comptent pas comme séries de travail. Repose-toi ${time(e.rest)} entre deux essais.</p></form>`}
function swapPanel(e){const candidates=swaps(e.id,state.profile.equipment).filter(x=>!state.active.exercises.some(it=>it.id===x.id));return `<section class="swap-panel"><h3>MÊME MOUVEMENT. AUTRE OPTION.</h3><p>${e.muscle} · même pattern. Chaque exercice garde sa propre calibration.</p>${candidates.length?candidates.map(x=>button(`${x.name}<small>${x.gear} · ${x.muscle}</small>`,'select-swap','choice',`data-value="${x.id}"`)).join(''):'<p>Aucun équivalent adapté avec ton matériel actuel. Ne remplace pas ce mouvement par un exercice d’un autre pattern.</p>'}${button('Fermer','swap','text-button')}</section>`}
function emom(a){const moves=[['Squat au banc','6–8 répétitions contrôlées'],['Pompes inclinées','5–8 répétitions, support stable'],['Marche dynamique sur place','20–30 secondes']];const current=moves[a.emomMinute%3];return `<p class="eyebrow">QUICK EMOM · TOUR ${Math.floor(a.emomMinute/3)+1} / 4</p><h1>MINUTE ${fmt(a.emomMinute+1)}<span class="muted"> / 12</span></h1><section class="set-card"><h2>${current[0]}</h2><p class="lead">${current[1]}</p><p>Commence au début de la minute sur ta Garmin. Termine en 30–40 secondes maximum ; repose-toi le reste de la minute. Si nécessaire, réduis les répétitions.</p><p>Garde 3 répétitions en réserve. Ce bloc développe surtout le conditionnement ; il ne remplace pas une mission MAIN.</p></section>${button(a.emomMinute===11?'DERNIÈRE MINUTE TERMINÉE ✓':'MINUTE ÉCOULÉE · SUIVANTE ↗','emom-next','primary big')}${button('Douleur / inconfort · arrêter','stop','text-button')}`}
function profile(){return `<p class="eyebrow">PARAMÈTRES PERSONNELS</p><h1>TON POINT<br>DE DÉPART.</h1><form id="profile-form"><div class="profile-grid"><section class="panel"><h3>TOI & TON OBJECTIF</h3><label>Prénom<input name="name" value="${esc(state.profile.name)}" maxlength="30" required></label><div class="field-pair">${[['weight','Poids (kg)',30,300],['fat','Masse grasse (%)',1,70],['muscle','Masse musculaire (kg)',1,200],['visceral','Indice viscéral',0,100],['bmr','Métabolisme estimé (kcal)',500,5000]].map(([key,label,min,max])=>`<label>${label}<input type="number" name="${key}" value="${state.profile[key]}" min="${min}" max="${max}" step="0.1" required></label>`).join('')}</div><p class="fine">Valeurs initiales issues de ta balance, modifiables. Ce sont des repères approximatifs ; elles ne déterminent jamais tes charges.</p></section><section class="panel"><h3>TON TERRAIN DE JEU</h3><p>Quel matériel est disponible dans ta salle ?</p>${equipment.map(e=>`<label class="check"><input type="checkbox" name="equipment" value="${e}" ${state.profile.equipment.includes(e)?'checked':''}>${e}</label>`).join('')}<hr><h3>3 MISSIONS / SEMAINE</h3><p>Lundi–vendredi, en séquence flexible. Samedi golf, dimanche repos. Au moins 36 h entre les missions, davantage si tu récupères mal.</p><label class="check"><input name="ready" type="checkbox" required ${state.profile.ready?'checked':''}>Je peux pratiquer ces mouvements sans douleur et je commence avec des charges légères.</label></section></div><button class="primary big" type="submit">ENREGISTRER MON PROFIL ↗</button></form><section class="line-section"><h3>TES DONNÉES RESTENT DANS CE NAVIGATEUR.</h3><p>Pas de compte ni de synchronisation Garmin dans cette V1. Exporte régulièrement une sauvegarde.</p>${button('Exporter mes données','export','outline')}<label class="import-label">Restaurer une sauvegarde<input id="import-file" type="file" accept="application/json,.json"></label></section>`}
function calendar(){const year=month.getFullYear(),m=month.getMonth(),first=new Date(year,m,1),offset=(first.getDay()+6)%7,days=new Date(year,m+1,0).getDate();return `<p class="eyebrow">CHAQUE SÉANCE LAISSE UNE TRACE</p><h1>MISSION LOG.</h1><div class="section-title"><h3>${month.toLocaleDateString('fr-FR',{month:'long',year:'numeric'}).toUpperCase()}</h3><div>${button('←','prev-month','icon','aria-label="Mois précédent"')}${button('→','next-month','icon','aria-label="Mois suivant"')}</div></div><div class="calendar">${['LUN','MAR','MER','JEU','VEN','SAM','DIM'].map(d=>`<span class="calendar-label">${d}</span>`).join('')}${'<div class="blank"></div>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=new Date(year,m,i+1),key=dayKey(d),ss=state.history.filter(s=>s.date===key),weekend=d.getDay()===0||d.getDay()===6;return `<div class="day ${weekend?'off':''} ${key===dayKey()?'today':''}"><b>${i+1}</b>${ss.map(s=>button(s.status==='complete'?`✓ ${s.type}`:'ÉCOURTÉE','history-detail','session-pill',`data-value="${s.id}"`)).join('')}${weekend?`<small>${d.getDay()===6?'GOLF':'REPOS'}</small>`:''}</div>`}).join('')}</div><section class="line-section"><h3>HISTORIQUE</h3>${state.history.length?[...state.history].reverse().map(s=>button(`<span>${s.date} · ${s.status==='complete'?'✓ Terminée':'Écourtée'}</span><strong>${s.title}</strong><span>${s.records.length} séries ↗</span>`,'history-detail','history-row',`data-value="${s.id}"`)).join(''):'<div class="empty"><strong>LE DÉBUT DE TON HISTOIRE.</strong><p>Ta première mission apparaîtra ici. Aucun retard, aucun jour à rattraper.</p><a href="#missions">Choisir ma mission ↗</a></div>'}</section>${selectedHistory?historyDetail():''}`}
function historyDetail(){const s=state.history.find(x=>x.id===selectedHistory);if(!s)return '';return `<section class="panel"><div class="section-title"><h3>${esc(s.title)} · ${s.date}</h3>${button('Fermer','close-history','text-button')}</div>${s.type==='EMOM'?`<p>${s.emomMinute} minutes validées · conditionnement</p>`:s.records.map(r=>`<p>${byId(r.id)?.name} · ${r.reps} reps · ${loadLabel(byId(r.id),r.weight,r.mode)} · réserve ${r.rir}${r.pain?' · douleur':''}</p>`).join('')}<p>Finisher : ${s.finisher||'aucun'}</p></section>`}
function progressPage(){const lv=level(state),v=volume(state);return `<p class="eyebrow">TES EFFORTS, VISIBLES</p><h1>LEVEL UP.</h1><div class="progress-grid"><section class="level-card"><span class="tag dark">RÉGULARITÉ</span><h2>LVL. ${fmt(lv.level)}</h2><progress max="300" value="${lv.within}"></progress><p>${lv.within} / 300 XP vers le prochain niveau</p><small>MAIN : 100 XP · QUICK / EMOM : 50 XP.<br>Ni bonus pour l’échec, ni entraînement risqué à débloquer.</small></section><section class="panel"><h3>VOLUME DE LA SEMAINE</h3><p>Séries directes réalisées. Les EMOM ne sont pas assimilés à des séries d’hypertrophie.</p>${['Quadriceps','Pectoraux','Dos','Ischios / fessiers','Épaules'].map(m=>`<div class="volume-row"><span>${m}</span><b>${v[m]||0} séries</b></div>`).join('')}<p class="fine">Départ progressif : 2 séries par exercice, puis 3 après 6 MAIN terminées. Ce repère de volume n’est pas une obligation à rattraper.</p></section></div><section class="line-section"><h3>TES PROCHAINES CHARGES</h3>${Object.keys(state.loads).length?Object.entries(state.loads).map(([id,l])=>`<div class="exercise-row"><div><h4>${byId(id).name}</h4><small>${esc(l.reason)}</small></div><b>${loadLabel(byId(id),l.weight,l.mode)}</b></div>`).join(''):'<div class="empty"><strong>ON APPREND À TE CONNAÎTRE.</strong><p>Calibre tes premiers exercices : les charges et les ajustements apparaîtront ici.</p></div>'}</section>`}
function science(){return `<p class="eyebrow">MOTEUR V1 / TRANSPARENT PAR CONCEPTION</p><h1>DES BASES<br>SOLIDES.</h1><div class="prose"><h3>Hypertrophie, avec une entrée progressive</h3><p>Les recommandations ACSM 2026 favorisent l’entraînement progressif et indiquent un bénéfice de volumes hebdomadaires plus élevés pour l’hypertrophie. La V1 commence volontairement plus bas : 2 séries par exercice pendant 6 MAIN, puis 3. Elle ne prétend pas calculer un optimum individuel.</p><h3>Une charge gagnée, pas devinée</h3><p>Calibration par essais légers, sans test 1RM. Cible : 8–12 répétitions et 2–3 répétitions en réserve. Toutes les séries à 12 avec au moins 2 en réserve : le plus petit palier disponible est proposé à la séance suivante. Sinon on conserve la charge ou on réduit d’un palier si elle est trop difficile. Cette règle est un choix prudent de programmation, pas une prescription exacte tirée d’une étude.</p><h3>Le repos fait partie du travail</h3><p>90 secondes sur les accessoires, 120–180 secondes sur les mouvements exigeants. 150 secondes de transition entre exercices, à prolonger si nécessaire. Les synthèses soutiennent l’intérêt d’éviter des repos trop courts ; le temps précis de transition est un choix pratique.</p><h3>Une progression qui a des limites</h3><p>Les estimations de réserve sont imparfaites chez un novice. Une douleur doit interrompre le mouvement. L’application ne diagnostique pas et ne gère pas une rééducation. Une séance écourtée conserve ses séries sans déclencher de hausse. Les QUICK ne font pas avancer A → B → C.</p><h3>Références</h3><p><a href="https://pubmed.ncbi.nlm.nih.gov/41843416/" target="_blank" rel="noreferrer">ACSM 2026 — synthèse de 137 revues systématiques ↗</a></p><p><a href="https://pubmed.ncbi.nlm.nih.gov/39205815/" target="_blank" rel="noreferrer">Singer et al., 2024 — repos entre séries et hypertrophie ↗</a></p><p><a href="https://pubmed.ncbi.nlm.nih.gov/38970765/" target="_blank" rel="noreferrer">Robinson et al., 2024 — proximité de l’échec et adaptations ↗</a></p></div>`}
function prepare(){const a=state.active;if(a.type==='EMOM'){a.stage='emom';return}const e=byId(a.exercises[a.index].id),l=prescription(state,e.id);a.stage=l.weight===null?'calibrate':'work'}
function nextExercise(){const a=state.active;if(a.index+1<a.exercises.length){a.index++;a.stage='rest';a.restKind='exercise';a.rest=150}else a.stage='finishers'}
function render(){if(!['missions','calendar','progress','profile','science'].includes(page))page='missions';$('#app').innerHTML=shell(({missions,calendar,progress:progressPage,profile,science})[page]());}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'missions';render();window.scrollTo(0,0)});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,value=b.dataset.value,a=state.active;
switch(action){case'dismiss':notice='';break;case'start-main':start('MAIN');return;case'start-quick':start('QUICK');return;case'start-emom':start('EMOM');return;case'warmup':a.warmup=value;prepare();break;case'continue':prepare();break;case'swap':swapping=!swapping;break;case'select-swap':a.exercises[a.index].id=value;swapping=false;prepare();break;case'recalibrate':if(byId(a.exercises[a.index].id).loadMode==='body'){notice='Poids du corps : ajuste la hauteur du support ou choisis un SWAP adapté.'}else a.stage='calibrate';break;case'pain':if(confirm('Arrêter ce mouvement et conserver la séance ? Aucune progression ne sera calculée pour cet exercice.')){a.records.push({id:a.exercises[a.index].id,pain:true,reps:0,weight:0,rir:0});notice='Mouvement arrêté. Si la douleur persiste, fais évaluer ce mouvement avant de le reprendre.';nextExercise()}break;case'stop':if(confirm('Enregistrer cette séance comme écourtée et quitter ?')){state=finishSession(state,a,'partial');notice='Séance écourtée enregistrée. La séquence principale reste inchangée.'}break;case'emom-next':a.emomMinute++;if(a.emomMinute>=12)a.stage='finishers';break;case'finisher':a.finisher=value;a.stage='finisher';break;case'skip-finisher':a.finisher=null;case'complete':{const stopped=a.records.some(r=>r.pain);state=finishSession(state,a,stopped?'partial':'complete');notice=stopped?'Séance enregistrée comme écourtée après une douleur. La séquence est conservée.':'MISSION ACCOMPLIE. Séance enregistrée, progression mise à jour.';}break;case'prev-month':month=new Date(month.getFullYear(),month.getMonth()-1,1);break;case'next-month':month=new Date(month.getFullYear(),month.getMonth()+1,1);break;case'history-detail':selectedHistory=value;break;case'close-history':selectedHistory=null;break;case'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`mo-training-${dayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}}
save();render()});
document.addEventListener('submit',event=>{event.preventDefault();const f=event.target,data=new FormData(f),a=state.active;
if(f.id==='profile-form'){const available=data.getAll('equipment');if(!available.length){notice='Sélectionne au moins un type de matériel.';render();return}state.profile={...state.profile,name:data.get('name').trim()||'Morgan',equipment:available,ready:true};for(const key of ['weight','fat','muscle','visceral','bmr'])state.profile[key]=Number(data.get(key));notice='Profil enregistré. Ta première charge sera calibrée pendant la mission.';save();go('missions');return}
if(f.id==='calibration-form'){const e=byId(a.exercises[a.index].id),weight=Number(data.get('weight')),step=Number(data.get('step')),rir=Number(data.get('rir')),mode=data.get('mode');if(rir!==3){notice=rir>3?`Trop facile : essaie ${weight+step} kg dans la même unité après ${time(e.rest)} de repos.`:`Trop lourd : réduis à ${Math.max(0,weight-step)} kg, ou davantage si nécessaire, après ${time(e.rest)} de repos.`;render();return}state.loads[e.id]={weight,step,mode,target:e.min,reason:'Charge calibrée. Garde 2–3 répétitions en réserve.'};a.stage='rest';a.rest=e.rest;a.restKind='set';notice='Calibration validée. Repose-toi avant la première série de travail.'}
if(f.id==='set-form'){const item=a.exercises[a.index],e=byId(item.id),l=prescription(state,e.id);a.records.push({id:e.id,weight:Number(data.get('weight')),reps:Number(data.get('reps')),rir:Number(data.get('rir')),mode:l.mode});const count=a.records.filter(r=>r.id===e.id).length;if(count>=item.sets)nextExercise();else{a.stage='rest';a.restKind='set';a.rest=e.rest}}
save();render()});
document.addEventListener('change',async event=>{if(event.target.id!=='import-file')return;const file=event.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error();const parsed=JSON.parse(await file.text());validateImport(parsed);if(confirm('Remplacer les données de ce navigateur par cette sauvegarde ?')){state=parsed;save();notice='Sauvegarde restaurée.';render()}}catch{notice='Sauvegarde invalide ou incompatible. Tes données actuelles sont conservées.';render()}});
function validateImport(s){if(s.active!==null){const a=s.active;if(!a||!['MAIN','QUICK','EMOM'].includes(a.type)||!['warmup','rest','calibrate','work','emom','finishers','finisher'].includes(a.stage)||!Array.isArray(a.exercises)||!a.exercises.length||a.exercises.some(x=>!byId(x.id)||!Number.isInteger(x.sets)||x.sets<1||x.sets>3)||!Number.isInteger(a.index)||a.index<0||a.index>=a.exercises.length||!Array.isArray(a.records)||a.records.some(r=>!byId(r.id)))throw Error();}if(s?.version!==1||!Array.isArray(s.history)||!s.profile||typeof s.profile.name!=='string'||!Array.isArray(s.profile.equipment)||s.profile.equipment.some(e=>!equipment.includes(e))||!s.loads)throw Error();for(const k of ['weight','fat','muscle','visceral','bmr'])if(!Number.isFinite(s.profile[k])||s.profile[k]<0)throw Error();for(const [id,l]of Object.entries(s.loads)){if(!byId(id)||!Number.isFinite(l.weight)||l.weight<0||!Number.isFinite(l.step)||l.step<0||!['body','pair','side','bar','unilateral','stack','single'].includes(l.mode))throw Error()}for(const h of s.history){if(!['MAIN','QUICK','EMOM'].includes(h.type)||!['partial','complete'].includes(h.status)||!/^\d{4}-\d{2}-\d{2}$/.test(h.date)||!Array.isArray(h.records)||!Number.isFinite(h.endedAt)||typeof h.title!=='string')throw Error();for(const r of h.records)if(!byId(r.id)||!Number.isFinite(r.reps)||!Number.isFinite(r.weight)||!Number.isFinite(r.rir))throw Error()}}
render();
